<?php
namespace App\Services;
use App\Models\Ingredient;use App\Models\StockBalance;use App\Models\StockCount;use App\Models\StockCountItem;use Illuminate\Contracts\Pagination\LengthAwarePaginator;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class StockCountItemService
{
 public function getAll(?string $search=null,?int $countId=null):LengthAwarePaginator{return StockCountItem::query()->with(['stockCount.stockLocation','ingredient.baseUnit'])->when($countId,fn(Builder $q)=>$q->where('stock_count_id',$countId))->when($search,fn(Builder $q)=>$q->whereHas('ingredient',fn(Builder $i)=>$i->where('name','like',"%$search%")->orWhere('code','like',"%$search%")))->orderByDesc('stock_count_id')->orderBy('id')->paginate(15)->withQueryString();}
 public function options():array{return ['counts'=>StockCount::query()->where('status','draft')->with('stockLocation')->orderByDesc('count_date')->get(),'ingredients'=>Ingredient::query()->with('baseUnit')->orderBy('name')->get(['id','code','name','base_unit_id'])];}
 public function create(array $data):StockCountItem{return DB::transaction(function()use($data):StockCountItem{$c=StockCount::query()->whereKey($data['stock_count_id'])->lockForUpdate()->firstOrFail();$this->draft($c);if($c->items()->where('ingredient_id',$data['ingredient_id'])->exists())throw ValidationException::withMessages(['ingredient_id'=>'This ingredient is already in the count.']);$b=StockBalance::query()->where('ingredient_id',$data['ingredient_id'])->where('stock_location_id',$c->stock_location_id)->first();$system=(float)($b?->quantity_on_hand??0);return $c->items()->create(['ingredient_id'=>$data['ingredient_id'],'system_quantity'=>$system,'counted_quantity'=>$data['counted_quantity'],'variance_quantity'=>round((float)$data['counted_quantity']-$system,3),'unit_cost'=>$b?->average_unit_cost??0]);});}
 public function update(StockCountItem $item,array $data):StockCountItem{return DB::transaction(function()use($item,$data):StockCountItem{$old=StockCount::query()->whereKey($item->stock_count_id)->lockForUpdate()->firstOrFail();$new=StockCount::query()->whereKey($data['stock_count_id'])->lockForUpdate()->firstOrFail();$this->draft($old);$this->draft($new);if(((int)$item->stock_count_id!==(int)$new->id||(int)$item->ingredient_id!==(int)$data['ingredient_id'])&&$new->items()->where('ingredient_id',$data['ingredient_id'])->where('id','!=',$item->id)->exists())throw ValidationException::withMessages(['ingredient_id'=>'This ingredient is already in the count.']);$balance=StockBalance::query()->where('ingredient_id',$data['ingredient_id'])->where('stock_location_id',$new->stock_location_id)->first();$system=(float)($balance?->quantity_on_hand??0);$item->update(['stock_count_id'=>$new->id,'ingredient_id'=>$data['ingredient_id'],'system_quantity'=>$system,'counted_quantity'=>$data['counted_quantity'],'variance_quantity'=>round((float)$data['counted_quantity']-$system,3),'unit_cost'=>$balance?->average_unit_cost??0]);return $item->refresh();});}
 public function delete(StockCountItem $item):bool{return DB::transaction(function()use($item):bool{$c=StockCount::query()->whereKey($item->stock_count_id)->lockForUpdate()->firstOrFail();return $c->status==='draft'&&(bool)$item->delete();});}
 private function draft(StockCount $c):void{if($c->status!=='draft')throw ValidationException::withMessages(['stock_count_id'=>'Count lines can only be changed while the count is a draft.']);}
}
